//! 🎯️ A retained common target borrows original operation paths and copies one bounded UTF-8 fragment at a time.
use super::ArtifactOperationTargets;
use semio_framework_value::{ValueError,ValueRefusalKind,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
use semio_framework_value::retained_clone::RetainedCloneClose;
use std::mem::{ManuallyDrop,size_of};
use semio_framework_replication_causal::binary::{DOCUMENT_BACKBONE_BATCH_MAXIMUM_IDENTIFIER_BYTES as MAXIMUM_SEGMENT,DOCUMENT_BACKBONE_BATCH_MAXIMUM_TARGET_SEGMENTS as MAXIMUM_SEGMENTS};
/// 🧳️ Original target strings and their backing remain attached through prefix selection and paid cancellation.
pub struct OriginalCommonTarget{values:ManuallyDrop<Option<Vec<String>>>,pending:ManuallyDrop<Option<String>>,retirement:RetainedCloneClose,source:Option<(usize,usize)>,initialized:bool,active:bool,building:bool,row:usize,offset:usize,limit:usize,truncating:bool,closing:bool}
impl Default for OriginalCommonTarget{fn default()->Self{Self{values:ManuallyDrop::new(None),pending:ManuallyDrop::new(None),retirement:Default::default(),source:None,initialized:false,active:false,building:false,row:0,offset:0,limit:0,truncating:false,closing:false}}}
fn invalid(text:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,text)}
fn source_key(source:Option<&dyn ArtifactOperationTargets>)->Option<(usize,usize)>{source.map(|source|(source as*const dyn ArtifactOperationTargets as*const()as usize,source.len()))}
fn header<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn permits(g:RetainedCloneGrant,d:RetirementDemand)->bool{semio_framework_value::retained_clone::retained_clone_grant_admits(g,d)}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
impl OriginalCommonTarget{
 /// 📏️ Captures only source coordinates and the first path's exact bounded vector backing.
 pub fn start_demands(&self,source:Option<&dyn ArtifactOperationTargets>)->Result<RetirementDemand,ValueError>{let count=source.map_or(0,ArtifactOperationTargets::len);if count>MAXIMUM_SEGMENTS{return Err(invalid("original conflict path exceeds its canonical segment bound"))}let capacity=if self.values.is_none(){count.checked_mul(size_of::<String>()).ok_or_else(||invalid("original conflict path extent overflow"))?}else{0};Ok(RetirementDemand{capacity_bytes:capacity,..header::<(Option<Vec<String>>,Option<(usize,usize)>,usize,usize,usize,bool,bool,bool)>()})}
 /// 🎟️ Starts one genuine path while preserving the current selected prefix and all its original owners.
 pub fn start(&mut self,source:Option<&dyn ArtifactOperationTargets>,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{if self.closing||self.active{return Err(invalid("original common target already retains an active path"))}let d=self.start_demands(source)?;if !permits(grant,d){return Ok(Default::default())}let count=source.map_or(0,ArtifactOperationTargets::len);if self.values.is_none(){let mut values=Vec::new();values.try_reserve_exact(count).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"original target backing allocation refused"))?;*self.values=Some(values);}self.source=source_key(source);self.active=true;self.building=!self.initialized;self.row=0;self.offset=0;self.limit=if self.building{count}else{count.min(self.values.as_ref().unwrap().len())};self.truncating=false;Ok(receipt(d))}
 /// 🏁️ A completed original path can be followed by another source or transferred to its actual publisher.
 pub fn source_finished(&self)->bool{self.initialized&&!self.active&&!self.closing}
 /// 📏️ Quotes one source read, target string birth, original trailing-owner close or bounded phase move.
 pub fn demands(&self,source:Option<&dyn ArtifactOperationTargets>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing{return self.close_demands(body)}if !self.active{return Ok(Default::default())}if self.source!=source_key(source){return Err(invalid("common target changed its original operation path"))}if !self.retirement.is_empty(){return Ok(RetirementDemand{copy_bytes:self.retirement.next_copy_byte_demand()?,capacity_bytes:self.retirement.next_capacity_byte_demand(body)?,release_bytes:self.retirement.next_release_byte_demand()?,depth:self.retirement.next_depth_demand()?})}if self.truncating{return if self.pending.is_some(){self.retirement.next_owner_demands::<String>(true,&None,body)}else{Ok(header::<(String,usize)>())}}if self.row==self.limit{return Ok(header::<(bool,bool,Option<(usize,usize)>)>())}let source=source.ok_or_else(||invalid("nonempty original target source disappeared"))?;let length=source.segment_len(self.row)?;if length>MAXIMUM_SEGMENT{return Err(invalid("original target identifier exceeds its canonical byte bound"))}if self.building&&self.pending.is_none(){return Ok(RetirementDemand{capacity_bytes:length,..header::<Option<String>>()})}if self.offset==length{return Ok(header::<(String,usize,usize)>())}Ok(RetirementDemand{copy_bytes:64+2*size_of::<usize>()+size_of::<bool>(),depth:1,..Default::default()})}
 /// 🪡️ Reads at most sixty-four original bytes; a different source is refused before any selected owner changes.
 pub fn advance(&mut self,source:Option<&dyn ArtifactOperationTargets>,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{if self.closing{return Err(invalid("closing common target cannot resume selection"))}if !self.active{return Ok(Default::default())}let d=self.demands(source,grant.maximum_copy_bytes)?;if !permits(grant,d){return Ok(Default::default())}if !self.retirement.is_empty(){return self.retirement.step_granted(grant).map(|step|step.progress())}if self.truncating{if self.pending.is_some(){return Ok(self.retirement.begin_granted(&mut self.pending,grant)?.map_or(Default::default(),|step|step.progress()))}let values=self.values.as_mut().unwrap();if values.len()>self.row{*self.pending=values.pop();}else{self.truncating=false;self.limit=self.row;}return Ok(receipt(d))}if self.row==self.limit{if !self.building&&self.values.as_ref().unwrap().len()>self.limit{self.truncating=true;}else{self.active=false;self.source=None;self.initialized=true;}return Ok(receipt(d))}let source=source.unwrap();let length=source.segment_len(self.row)?;if self.building&&self.pending.is_none(){*self.pending=Some(String::with_capacity(length));return Ok(receipt(d))}if !self.building&&self.values.as_ref().unwrap()[self.row].len()!=length{self.truncating=true;return Ok(receipt(d))}if self.offset==length{if self.building{self.values.as_mut().unwrap().push(self.pending.take().unwrap());}self.row+=1;self.offset=0;return Ok(receipt(d))}let mut fragment=[0;64];let count=source.read_segment(self.row,self.offset,&mut fragment[..(length-self.offset).min(64)])?;if count==0||count>(length-self.offset).min(64){return Err(invalid("original target codec changed its declared segment extent"))}if self.building{let valid=match std::str::from_utf8(&fragment[..count]){Ok(_)=>count,Err(error)if error.error_len().is_none()=>error.valid_up_to(),Err(_)=>return Err(invalid("original target codec produced invalid UTF-8"))};if valid==0{return Err(invalid("original target codec split a scalar without a bounded continuation"))}self.pending.as_mut().unwrap().push_str(std::str::from_utf8(&fragment[..valid]).unwrap());self.offset+=valid;}else if self.values.as_ref().unwrap()[self.row].as_bytes().get(self.offset..self.offset+count)!=Some(&fragment[..count]){self.truncating=true;}else{self.offset+=count;}Ok(receipt(d))}
 /// 🤝️ Transfers the exact admitted common path without cloning any segment.
 pub fn take(&mut self,grant:RetainedCloneGrant)->Result<Option<(Vec<String>,RetainedCloneProgress)>,ValueError>{if !self.source_finished(){return Err(invalid("common target selection has not finished"))}let d=header::<Option<Vec<String>>>();if !permits(grant,d){return Ok(None)}let values=self.values.take().unwrap();self.initialized=false;Ok(Some((values,receipt(d))))}
 /// 🛑️ Keeps every partial original string and vector available to paid closure.
 pub fn begin_close(&mut self){self.closing=true;}
 /// 📏️ Prices exact child retirement independently of source body credit.
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty(){return Ok(RetirementDemand{copy_bytes:self.retirement.next_copy_byte_demand()?,capacity_bytes:self.retirement.next_capacity_byte_demand(body)?,release_bytes:self.retirement.next_release_byte_demand()?,depth:self.retirement.next_depth_demand()?})}if self.pending.is_some(){return self.retirement.next_owner_demands::<String>(true,&None,body)}if self.values.is_some(){return self.retirement.next_owner_demands::<Vec<String>>(true,&None,body)}Ok(header::<(Option<(usize,usize)>,bool)>())}
 /// ♻️ Returns original partial strings, selected path backing and close frames before releasing source coordinates.
 pub fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.begin_close();if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demands(grant.maximum_copy_bytes)?;if !permits(grant,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.retirement.is_empty(){return self.retirement.step_granted(grant)}if self.pending.is_some(){return Ok(self.retirement.begin_granted(&mut self.pending,grant)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}if self.values.is_some(){return Ok(self.retirement.begin_granted(&mut self.values,grant)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}self.source=None;self.active=false;Ok(RetainedCloneStep::Progress(receipt(d)))}
 /// 🫙️ Original source coordinates and all string/vector retirement owners must be empty together.
 pub fn terminal_is_empty(&self)->bool{self.values.is_none()&&self.pending.is_none()&&self.retirement.is_empty()&&self.source.is_none()&&!self.active}
}
impl Drop for OriginalCommonTarget{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"original common target must transfer or physically close");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.values);ManuallyDrop::drop(&mut self.pending);}}}}

